:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #0f3460;
  --x-color: #e94560;
  --o-color: #f5c542;
  --text: #eaeaea;
  --win-bg: #2d6a4f;
  --cell-bg: #0f3460;
  --cell-hover: #1b4b7a;
  --cell-focus: #e94560;
  --border: #eaeaea;
  font-size: 16px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  color: var(--text);
  padding: 1rem;
}

.game-card {
  background: var(--card);
  border: 4px solid var(--border);
  border-radius: 0;
  padding: 2rem 1.5rem;
  max-width: 420px;
  width: 100%;
  text-align: center;
  image-rendering: pixelated;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 0.75rem;
  color: var(--x-color);
  text-shadow: 2px 2px 0 #000;
}

.status {
  font-size: 1.125rem;
  margin-bottom: 1.5rem;
  min-height: 1.5em;
  font-weight: 600;
  letter-spacing: 1px;
}

.board {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin-bottom: 1.5rem;
  background: var(--border);
  padding: 6px;
  border: 4px solid var(--border);
}

.cell {
  aspect-ratio: 1 / 1;
  background: var(--cell-bg);
  border: none;
  font-family: inherit;
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--text);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.1s;
  padding: 0;
  line-height: 1;
  image-rendering: pixelated;
  box-shadow: inset -4px -4px 0 rgba(0, 0, 0, 0.3);
}

.cell:hover:not(:disabled) {
  background: var(--cell-hover);
}

.cell:focus-visible {
  outline: 4px solid var(--cell-focus);
  outline-offset: -4px;
  z-index: 1;
}

.cell:active:not(:disabled) {
  transform: translateY(2px);
  box-shadow: inset 4px 4px 0 rgba(0, 0, 0, 0.3);
}

.cell.x {
  color: var(--x-color);
}

.cell.o {
  color: var(--o-color);
}

.cell.win {
  background: var(--win-bg);
  animation: pulse 0.6s ease-in-out infinite alternate;
}

@keyframes pulse {
  from { opacity: 1; }
  to { opacity: 0.75; }
}

.cell:disabled {
  cursor: default;
}

.restart-btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  padding: 0.75rem 2rem;
  background: var(--x-color);
  color: #fff;
  border: 3px solid var(--border);
  border-radius: 0;
  cursor: pointer;
  box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.4);
  transition: background 0.1s, transform 0.05s;
}

.restart-btn:hover {
  background: #c73a52;
}

.restart-btn:focus-visible {
  outline: 4px solid var(--o-color);
  outline-offset: 3px;
}

.restart-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 rgba(0, 0, 0, 0.4);
}

@media (max-width: 400px) {
  .game-card {
    padding: 1.25rem 0.75rem;
  }
  h1 {
    font-size: 1.25rem;
  }
  .cell {
    font-size: 2rem;
  }
  .board {
    gap: 4px;
    padding: 4px;
  }
}

const boardEl = document.getElementById('board');
const statusEl = document.getElementById('status');
const restartBtn = document.getElementById('restart');

const WIN_LINES = [
  [0,1,2], [3,4,5], [6,7,8],
  [0,3,6], [1,4,7], [2,5,8],
  [0,4,8], [2,4,6]
];

let board, currentPlayer, gameOver, winningLine;

function init() {
  board = Array(9).fill('');
  currentPlayer = 'X';
  gameOver = false;
  winningLine = null;
  renderBoard();
  updateStatus();
}

function renderBoard() {
  boardEl.innerHTML = '';
  board.forEach((mark, i) => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'cell';
    btn.dataset.index = i;
    btn.setAttribute('role', 'gridcell');
    btn.setAttribute('aria-label', `Cell ${i + 1}${mark ? ', ' + mark : ', empty'}`);
    if (mark) {
      btn.textContent = mark;
      btn.classList.add(mark.toLowerCase());
      btn.disabled = true;
    }
    if (winningLine && winningLine.includes(i)) {
      btn.classList.add('win');
    }
    btn.addEventListener('click', handleCellClick);
    boardEl.appendChild(btn);
  });
}

function handleCellClick(e) {
  const idx = Number(e.currentTarget.dataset.index);
  if (gameOver || board[idx]) return;
  board[idx] = currentPlayer;
  const win = checkWin(currentPlayer);
  if (win) {
    gameOver = true;
    winningLine = win;
    renderBoard();
    statusEl.textContent = `Player ${currentPlayer} wins!`;
    return;
  }
  if (board.every(cell => cell)) {
    gameOver = true;
    renderBoard();
    statusEl.textContent = "It's a draw!";
    return;
  }
  currentPlayer = currentPlayer === 'X' ? 'O' : 'X';
  renderBoard();
  updateStatus();
}

function checkWin(player) {
  for (const line of WIN_LINES) {
    if (line.every(i => board[i] === player)) return line;
  }
  return null;
}

function updateStatus() {
  statusEl.textContent = `Player ${currentPlayer}'s turn`;
}

restartBtn.addEventListener('click', init);

init();
